(x, y, t) => {
  const cx = 240, cy = 120;
  const sources = [
    [160 + Math.sin(t*0.6)*100, 80 + Math.cos(t*0.4)*50, 0.08, 2.0],
    [320 + Math.cos(t*0.5)*100, 160 + Math.sin(t*0.7)*50, 0.1, 1.7],
    [240 + Math.sin(t*0.3+2)*140, 120 + Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120 + Math.cos(t*0.8+4)*80, 180 + Math.sin(t*0.6+3)*60, 0.12, 1.4],
    [360 + Math.sin(t*0.4+1)*90, 60 + Math.cos(t*0.9+2)*70, 0.09, 1.9],
  ];
  let act = 0, inh = 0;
  for (const [sx, sy, freq, spd] of sources) {
    const d = Math.sqrt((x-sx)**2 + (y-sy)**2);
    act += Math.sin(d*freq - t*spd);
    inh += Math.cos(d*freq*0.7 - t*spd*0.6) * 0.8;
  }
  act /= sources.length; inh /= sources.length;
  const warp = Math.sin(x*0.04 + t*0.5) * Math.cos(y*0.035 - t*0.3) * 15;
  const warp2 = Math.cos(x*0.025 - t*0.4) * Math.sin(y*0.045 + t*0.7) * 12;
  const dx = x + warp, dy = y + warp2;
  const dist = Math.sqrt((dx-cx)**2 + (dy-cy)**2);
  const ang = Math.atan2(dy-cy, dx-cx);
  const rad1 = Math.sin(dist*0.04 - t*1.5), rad2 = Math.sin(dist*0.025 + t*0.8);
  const ang1 = Math.sin(ang*6 + t*0.4), ang2 = Math.cos(ang*8 - t*0.6);
  const spiral = Math.sin(dist*0.03 - ang*3 + t*1.2);
  const layer2 = Math.tanh((rad1*0.4 + rad2*0.3 + ang1*0.3 + ang2*0.2 + spiral*0.4) * 1.8);
  const micro = Math.sin(x*0.15+t*3)*Math.sin(y*0.12-t*2.5)*0.12;
  const react = act - inh*0.7 + micro;
  const spot = Math.tanh(react * 2.8);
  const edge = Math.tanh((spot - layer2) * 3);
  const blend = spot*0.45 + layer2*0.35 + edge*0.2;
  const v = blend*0.5+0.5;
  const pal = [
    [8,12,48],[15,55,95],[25,110,140],[80,180,165],
    [220,195,80],[240,140,60],[200,65,50],[140,30,60],[60,15,55],[8,12,48]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82 + Math.sin(react*Math.PI*1.5)*0.12 + Math.abs(edge)*0.06;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum)|0
  ];
}
